        if _storage._timestampUnixNano != rhs_storage._timestampUnixNano {return false}
        if _storage._baseRevision != rhs_storage._baseRevision {return false}
        if _storage._rowCopies != rhs_storage._rowCopies {return false}
        if _storage._fullReplace != rhs_storage._fullReplace {return false}
        return true
      }
      if !storagesAreEqual {return false}
    }
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
